from sympy import *
from sympy.parsing.sympy_parser import parse_expr, standard_transformations, implicit_multiplication_application
T = standard_transformations + (implicit_multiplication_application,)
x, n, m, r, a, b, t = symbols('x n m r a b t')
def P(s): return parse_expr(s.split('=')[-1].replace('−','-').replace(',',''), transformations=T, local_dict={'x':x,'n':n,'m':m,'r':r,'a':a,'b':b,'t':t})
def pick(C, target):
    ok = [c for c in C if simplify(P(c) - target) == 0]
    assert len(ok) == 1, ok
    return ok[0].replace('−','-')
result = pick(['f(x) = (5/2)x + 3', 'f(x) = (2/5)x + 3', 'f(x) = 10x + 3', 'f(x) = 4x + 10'], Rational(10,4)*x + 3)

